import {mountDashboard,icon} from './dashboard.mjs';
import {currencyFields,CURRENCIES,historyHTML,renderHistory} from './transfer-ui.mjs';
import {createFundingService} from './funding-service.mjs';
import {fromUnits,toUnits} from './funding-catalog.mjs';
export function withdrawalHTML(){return '<div class="deposit-page"><div class="deposit-page-heading"><span class="deposit-heading-icon">'+icon('withdraw')+'</span><div><h1>Withdrawal Simulation</h1><p>Try the withdrawal flow using your site balance</p></div></div><div class="deposit-columns"><section class="deposit-panel"><h2>'+icon('wallet')+' New Simulation</h2><div class="payment-important"><strong>Simulation only</strong><p>No cryptocurrency is sent. The amount is held from your available site balance until you cancel the simulation.</p></div><div class="deposit-current-balance"><span>Available Balance</span><strong id="withdraw-balance">Sign in to view balance</strong></div><form id="withdraw-form"><div id="withdraw-currency-fields">'+currencyFields('withdraw')+'</div><div class="transfer-field"><label for="withdraw-amount">Amount to hold</label><input id="withdraw-amount" inputmode="decimal" placeholder="0.00" required></div><dl class="withdraw-summary"><div><dt>Network fee</dt><dd>Not charged · simulation</dd></div><div><dt>On-chain payout</dt><dd>None</dd></div><div><dt>Reserved balance</dt><dd id="withdraw-reserved">—</dd></div></dl><button type="submit" class="deposit-continue">Simulate Withdrawal</button><p id="withdraw-feedback" class="transfer-caption" role="status"></p></form></section>'+historyHTML('withdraw')+'</div></div>';}
export function mountWithdrawal(root,options={}){mountDashboard(root,{...options,view:'withdraw',mainHTML:withdrawalHTML()});let asset='BTC',network='bitcoin',service=null,data={balances:[],history:[]},id=crypto.randomUUID(),busy=false;const feedback=root.querySelector('#withdraw-feedback'),submit=root.querySelector('#withdraw-form button[type="submit"]');submit.disabled=true;
 function balances(){const b=data.balances.find(b=>b.asset===asset);root.querySelector('#withdraw-balance').textContent=(b?.available||'0')+' '+asset;root.querySelector('#withdraw-reserved').textContent=(b?.reserved||'0')+' '+asset;}
 async function refresh(){data=await service.load();balances();renderHistory(root.querySelector('#funding-history'),data.history.filter(r=>r.kind==='simulation'),{cancel:async(row,button)=>{button.disabled=true;try{await service.cancel(row.id);await refresh();feedback.textContent='Simulation cancelled. The held amount is available again.';}catch(e){feedback.textContent=e.message;button.disabled=false;}}});}
 function bind(){root.querySelector('#withdraw-currency').onchange=e=>{asset=e.target.value;network=CURRENCIES[asset].networks[0];root.querySelector('#withdraw-currency-fields').innerHTML=currencyFields('withdraw',asset,network);bind();balances();};root.querySelector('#withdraw-network').onchange=e=>network=e.target.value;}
 bind();root.querySelector('#withdraw-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;submit.disabled=true;feedback.textContent='';try{if(!service)throw Error('Sign in to simulate a withdrawal.');const amount=fromUnits(toUnits(root.querySelector('#withdraw-amount').value,asset),asset);await service.create('simulation',asset,network,amount,id);id=crypto.randomUUID();await refresh();feedback.textContent='Simulation created. '+amount+' '+asset+' is held from your available balance. No funds were sent.';}catch(e){feedback.textContent=e.message;}finally{busy=false;submit.disabled=!service;}};
 if(!options.preview)Promise.resolve(options.getAccounts?.()).then(async accounts=>{if(!accounts)return;service=createFundingService(accounts);await refresh();submit.disabled=false;}).catch(e=>feedback.textContent=e.message);window.scrollTo(0,0);
}
